// External libraries are loaded lazily so one CDN failure cannot blank the entire site.
let initializeApp, getAuth, GoogleAuthProvider, signInWithPopup, signInWithRedirect;
let signInWithEmailAndPassword, createUserWithEmailAndPassword, sendPasswordResetEmail;
let sendEmailVerification, signOut, onAuthStateChanged, RecaptchaVerifier, signInWithPhoneNumber;
let THREE=null;
let firebaseLoadError=null;

async function loadFirebase(){
  if(initializeApp) return true;
  try{
    const appMod=await import('https://www.gstatic.com/firebasejs/12.1.0/firebase-app.js');
    const authMod=await import('https://www.gstatic.com/firebasejs/12.1.0/firebase-auth.js');
    ({initializeApp}=appMod);
    ({getAuth,GoogleAuthProvider,signInWithPopup,signInWithRedirect,signInWithEmailAndPassword,createUserWithEmailAndPassword,sendPasswordResetEmail,sendEmailVerification,signOut,onAuthStateChanged,RecaptchaVerifier,signInWithPhoneNumber}=authMod);
    return true;
  }catch(e){ firebaseLoadError=e; return false; }
}

async function loadThree(){
  if(THREE) return THREE;
  const mod=await import('https://cdn.jsdelivr.net/npm/three@0.181.2/build/three.module.js');
  THREE=mod;
  return THREE;
}

