function persist(){localStorage.setItem('ss-theme',state.theme);localStorage.setItem('ss-kind',state.kind);localStorage.setItem('ss-parent',state.parent);localStorage.setItem('ss-type',state.type);localStorage.setItem('ss-batch',state.batch||'');localStorage.setItem('ss-qcount',state.quiz.count);localStorage.setItem('ss-shield',JSON.stringify(state.shield));localStorage.setItem('ss-profile-name',state.profile.name||'');localStorage.setItem('ss-profile-email',state.profile.email||'');if(state.profile.photo)localStorage.setItem('ss-profile-photo',state.profile.photo)}
function node(){return (state.kind==='exam'?CATALOG.exams:CATALOG.courses)[state.parent]}
function parents(){return Object.keys(state.kind==='exam'?CATALOG.exams:CATALOG.courses)}
function types(){return node()?.types||[]}; function batches(){const base=node()?.batches?.[state.type]||[];const added=(state.catalogChanges||[]).filter(x=>x.kind==='batch'&&x.parent===state.parent&&x.type===state.type).map(x=>x.name).filter(Boolean);return [...new Set([...base,...added])]}; function subjects(){return node()?.subjects?.[state.type]||[]}
function ensure(){if(!parents().includes(state.parent))state.parent=parents()[0];if(!types().includes(state.type))state.type=types()[0];if(!batches().includes(state.batch))state.batch=batches()[0]||'';if(state.parent==='SSC' && state.type==='SSC CGL Tier 1' && !localStorage.getItem('ss-type'))state.type='SSC CHSL';persist()}
function options(a,v){return a.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function header(){return `<header class="header"><div class="brand"><img src="/static/assets/hero-logo-reference-user.png" alt="SamStudy logo" onerror="this.onerror=null;this.src='/static/assets/samstudy-logo.png'"><b>SamStudy</b></div><div class="spacer"></div><button class="icon-btn" onclick="toggleTheme()">${state.theme==='dark'?'☾':'☀'}</button><button class="profile-btn" onclick="go('profile')">${state.authUser?'Profile':'Login / Sign up'}</button></header>`}
function nav(){const items=[['home','⌂','Home'],['batches','▦','Batches'],['quiz','✓','Quiz'],['test','⏱','Tests'],['profile','●','Profile']];return `<nav class="bottom">${items.map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')"><span>${x[1]}</span>${x[2]}</button>`).join('')}</nav>`}
function selector(label='HOME · COURSE / EXAM'){ensure();return `<section class="selector"><div class="eyebrow">${label}</div><div class="selector-grid"><div class="field"><label>Course / Exam</label><select id="kind"><option value="exam" ${state.kind==='exam'?'selected':''}>Government Exam</option><option value="course" ${state.kind==='course'?'selected':''}>Course</option></select></div><div class="field"><label>${state.kind==='exam'?'Government Exam':'Course'}</label><select id="parent">${options(parents(),state.parent)}</select></div><div class="field"><label>${state.kind==='exam'?'Exam Type':'Course Type'}</label><select id="type">${options(types(),state.type)}</select></div></div></section>`}
