async function generateChapterPDF(){
  const r=state.resource||{}; const chapter=$('#chapterName')?.value.trim()||r.chapter||'';
  if(!r.subject||!chapter)return toast('Select or enter a chapter first');
  const box=$('#notesStatus'); if(box)box.textContent='Gemini is preparing the chapter PDF…';
  try{const d=await api('/api/ai/notes',{exam:state.parent,type:state.type,subject:r.subject,chapter});
    if(box)box.innerHTML=`<span>PDF ready. <a href="${esc(d.download)}" target="_blank" rel="noopener">Open / download notes</a></span>`;
  }catch(e){if(box)box.textContent=e.message;}
}
async function openLectureSearch(){
  const r=state.resource||{}; const chapter=$('#lectureChapter')?.value.trim()||r.chapter||'';
  try{const q=new URLSearchParams({subject:r.subject||'',chapter,type:state.type||''}); const d=await fetch('/api/lectures?'+q.toString()).then(x=>x.json()); if(d.url)window.open(d.url,'_blank','noopener'); else toast('Lecture search unavailable');}
  catch(e){toast('Could not open lecture search');}
}
function batchesPage(){const bs=batches();return `<main class="page"><div class="page-heading"><div><div class="eyebrow">BATCHES · ${esc(state.parent)}</div><h1>Your batches, directly.</h1><p>${state.kind==='exam'?esc(state.type):esc(state.parent+' · '+state.type)} · select one batch to open its subjects.</p></div></div>${selector('BATCH FILTER · HOME-STYLE SELECTOR')}<div class="cards">${bs.map((b,i)=>`<article class="card"><div class="badge">${i+1}</div><h3>${esc(b)}</h3><p>${subjects().length} subjects · each subject has Notes and Lectures.</p><button class="primary" onclick="openBatch('${encodeURIComponent(b)}')">Open Subjects →</button></article>`).join('')}</div>${!bs.length?`<div class="card"><p>No batches are configured for this track yet.</p></div>`:''}${isAdmin()?`<div class="section-title"><div class="eyebrow">DEVELOPER</div><h2>Add a batch</h2></div><div class="card admin-grid"><div class="field"><label>Batch name</label><input id="newBatch" placeholder="SSC CHSL Target Batch"></div><div class="field"><label>Track</label><input value="${esc(state.parent)} · ${esc(state.type)}" disabled></div><div class="full"><button class="primary" onclick="addBatch()">Add Batch</button></div></div>`:''}</main>`}
function subjectsPage(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">${esc(state.parent)} · ${esc(state.type)} · BATCH</div><h1>${esc(state.batch||'Selected Batch')}</h1><p>All subjects for this particular exam/course. Each subject opens chapter-wise Notes and Lectures.</p></div></div><div class="selector"><div class="eyebrow">SELECTED TRACK</div><div class="mini-row"><span class="mini-pill">${esc(state.parent)}</span><span class="mini-pill">${esc(state.type)}</span><span class="mini-pill">${esc(state.batch||'Batch')}</span></div></div><div class="subject-grid">${subjects().map((s,i)=>{const ch=chapterList(s);return `<article class="subject-card"><div class="subject-icon">${['∑','⚛','▣','◈','∴','⌁'][i%6]}</div><h3>${esc(s)}</h3><p>${ch.length} chapters · Notes · Lectures · AI PDF notes</p><div class="chapter-list">${ch.map((c,j)=>`<div class="chapter-row"><span>${j+1}. ${esc(c)}</span><span class="chapter-actions"><button onclick="openChapterNotes('${encodeURIComponent(s)}','${esc(c).replace(/'/g,'&#39;')}')">Notes</button><button onclick="openChapterLectures('${encodeURIComponent(s)}','${esc(c).replace(/'/g,'&#39;')}')">Lectures</button></span></div>`).join('')}</div><div class="resource-row"><button onclick="openResource('${encodeURIComponent(s)}','Notes')">All Notes</button><button onclick="openResource('${encodeURIComponent(s)}','Lectures')">All Lectures</button></div></article>`}).join('')}</div></main>`}
function resourcePage(){const r=state.resource||{subject:subjects()[0]||'Subject',kind:'Notes',chapter:''};const isNotes=r.kind==='Notes';const ch=esc(r.chapter||'');return `<main class="page"><div class="page-heading"><div><div class="eyebrow">${esc(r.kind).toUpperCase()} · ${esc(state.parent)} · ${esc(state.type)}</div><h1>${esc(r.subject)}</h1><p>${esc(state.batch||'Selected batch')} · ${isNotes?'Chapter-wise AI notes and downloadable PDFs.':'Exam/course + subject lecture search on YouTube.'}</p></div></div>${isNotes?`<div class="card"><div class="badge">PDF</div><h3>Chapter Notes Generator</h3><p>Choose or enter a chapter. Gemini creates structured notes with book-style mathematical notation and a downloadable PDF.</p><div class="field"><label>Chapter / Topic</label><input id="chapterName" value="${ch}" placeholder="e.g. Quadratic Equations"></div><div class="mini-row">${chapterList(r.subject).slice(0,12).map(c=>`<button class="mini-pill" onclick="document.getElementById('chapterName').value='${esc(c).replace(/'/g,'&#39;')}'">${esc(c)}</button>`).join('')}</div><div class="actions"><button class="primary" onclick="generateChapterPDF()">Generate PDF Notes with Gemini</button></div><div id="notesStatus" class="auth-note"></div></div>`:`<div class="card"><div class="badge">▶</div><h3>Lecture Library</h3><p>Search lectures for this exact exam/course, subject and chapter.</p><div class="field"><label>Chapter / Topic (optional)</label><input id="lectureChapter" value="${ch}" placeholder="e.g. Quadratic Equations"></div><button class="primary" onclick="openLectureSearch()">Open Lectures on YouTube</button></div>`}<div class="card"><h3>Developer resources</h3><p>${resourcesFor(r.subject,r.kind).length?'Uploaded resources are available for this subject.':'No uploaded resource has been added yet.'}</p>${resourcesFor(r.subject,r.kind).map(x=>`<a class="secondary" style="display:inline-flex;margin:5px 0;text-decoration:none" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open resource →</a>`).join('')}</div></main>`}
function quizPage(){if(state.quiz.submitted)return quizAnalysisPage();if(!state.quiz.questions.length)return `<main class="page"><div class="page-heading"><div><div class="eyebrow">AI QUIZ · 60 / 30 / 10</div><h1>Generate your quiz</h1><p>Gemini creates a set using the selected exam and subject. PYQ items are required to include a source/date; unverified items are not labelled as PYQ.</p></div></div>${selector('QUIZ · TRACK')}<div class="card"><div class="field"><label>Number of Questions</label><select id="quizCount"><option value="5" ${state.quiz.count===5?'selected':''}>5 Questions</option><option value="10" ${state.quiz.count===10?'selected':''}>10 Questions</option><option value="15" ${state.quiz.count===15?'selected':''}>15 Questions</option><option value="20" ${state.quiz.count===20?'selected':''}>20 Questions</option></select></div><div class="actions"><button class="primary" onclick="generateQuiz()">Generate Live Quiz with Gemini</button></div><div class="mini-row"><span class="mini-pill">60% PYQ</span><span class="mini-pill">30% PYQ-type</span><span class="mini-pill">10% hardest</span></div></div></main>`;const q=state.quiz.questions[state.quiz.i],sel=state.quiz.answers[state.quiz.i];return `<main class="page"><div class="page-heading"><div><div class="eyebrow">AI QUIZ · ${state.quiz.i+1}/${state.quiz.questions.length}</div><h1>${esc(state.type)} Quiz</h1><p>Tap the selected answer again to deselect it. Deselect stays available until Next/Submit.</p></div></div>${selector('QUIZ · TRACK')}<div class="stats"><div class="stat"><strong>${state.quiz.i+1}/${state.quiz.questions.length}</strong><span>Question</span></div><div class="stat"><strong data-live-timer>${fmtTime(nowSec())}</strong><span>Current time</span></div><div class="stat"><strong>${Object.values(state.quiz.answers).filter(v=>v!==null&&v!==undefined).length}</strong><span>Attempted</span></div><div class="stat"><strong>${q.sourceType||'AI'}</strong><span>Question type</span></div></div><br><div class="question"><div class="question-meta"><span>${esc(q.subject||'')}</span><span>${esc(q.source||'Gemini generated')}</span></div><h2>${esc(q.question)}</h2>${q.options.map((o,i)=>`<button class="option ${sel===i?'selected':''}" onclick="quizPick(${i})"><span class="dot"></span><span>${esc(o)}</span></button>`).join('')}<div class="actions"><button class="secondary" onclick="quizNext()">Next →</button><button class="primary" onclick="quizSubmit()">Submit Quiz</button></div><p style="color:var(--muted)">Time for this question is measured from when it opens until Next or Submit.</p></div></main>`}
function quizPick(i){state.quiz.answers[state.quiz.i]=state.quiz.answers[state.quiz.i]===i?null:i;render()}
function commitQuizTime(){state.quiz.times[state.quiz.i]=(state.quiz.times[state.quiz.i]||0)+nowSec();state.activeStartedAt=Date.now()}
function quizNext(){commitQuizTime();if(state.quiz.i<state.quiz.questions.length-1){state.quiz.i++;state.activeStartedAt=Date.now();render()}else quizSubmit()}
function quizSubmit(){commitQuizTime();state.quiz.submitted=true;render()}
function quizAnalysisPage(){const qs=state.quiz.questions;let attempted=0,right=0,total=0;qs.forEach((q,i)=>{const a=state.quiz.answers[i];if(a!==null&&a!==undefined){attempted++;if(a===q.answer)right++}total+=state.quiz.times[i]||0});const wrong=attempted-right;return `<main class="page"><div class="page-heading"><div><div class="eyebrow">QUIZ ANALYSIS</div><h1>Result & solutions</h1><p>Every question shows the answer and the time from open to Next/Submit.</p></div></div><div class="stats"><div class="stat"><strong>${attempted}</strong><span>Attempted</span></div><div class="stat"><strong>${right}</strong><span>Right</span></div><div class="stat"><strong>${wrong}</strong><span>Wrong</span></div><div class="stat"><strong>${attempted?Math.round(right/attempted*100):0}%</strong><span>Accuracy</span></div></div><br><div class="stats"><div class="stat"><strong>${fmtTime(total)}</strong><span>Total Time</span></div><div class="stat"><strong>${fmtTime(qs.length?Math.round(total/qs.length):0)}</strong><span>Avg / Question</span></div><div class="stat"><strong>${qs.length}</strong><span>Total Questions</span></div><div class="stat"><strong>${qs.length-attempted}</strong><span>Unattempted</span></div></div><div class="section-title"><div class="eyebrow">QUESTION-WISE</div><h2>Answer + time taken</h2></div><div class="analysis-list">${qs.map((q,i)=>{const a=state.quiz.answers[i],attempted=a!==null&&a!==undefined;return `<article class="analysis-q"><div class="question-meta"><span>Q${i+1} · ${esc(q.sourceType||'AI')}</span><span>⏱ ${fmtTime(state.quiz.times[i]||0)}</span></div><h3>${esc(q.question)}</h3>${q.options.map((o,j)=>`<div class="ans ${j===q.answer?'green':''} ${attempted&&a===j&&a!==q.answer?'red':''}">${attempted&&a===j?'● Selected · ':''}${j===q.answer?'✓ Correct · ':''}${esc(o)}</div>`).join('')}<div class="solution"><strong>Solution</strong><br>${esc(q.explanation||'')}</div></article>`}).join('')}</div><div class="actions"><button class="primary" onclick="resetQuiz()">New Quiz</button></div></main>`}
function resetQuiz(){state.quiz={questions:[],i:0,selected:null,answers:{},times:{},submitted:false,count:state.quiz.count,startedAt:Date.now()};state.activeStartedAt=Date.now();render()}
function testPage(){if(state.test.submitted)return testAnalysisPage();if(!state.test.questions.length)return `<main class="page"><div class="page-heading"><div><div class="eyebrow">REAL EXAM TEST · 70 / 20 / 10</div><h1>Generate full test</h1><p>70% PYQ · 20% PYQ-type · 10% hardest. Answer can be changed or cleared until Final Submit.</p></div></div>${selector('TEST · TRACK')}<div class="card"><div class="mini-row"><span class="mini-pill">70% PYQ</span><span class="mini-pill">20% PYQ-type</span><span class="mini-pill">10% hardest</span></div><div class="exam-pattern-box"><strong>Official-style pattern for ${esc(state.type)}</strong><div>${examPattern().questions} Questions · ${examPattern().timeMin} min · ${examPattern().marksPerQuestion} mark/question · −${examPattern().negativeSession2??examPattern().negative} (Session II where applicable) · ${examPattern().totalMarks} marks</div><div class="app-note">${examPattern().sections.map(x=>esc(x[0])+(x[1]?": "+x[1]:"")).join(" · ")}</div></div><div class="actions"><button class="primary" onclick="generateTest()">Generate Live Test with Gemini</button></div></div></main>`;const q=state.test.questions[state.test.i],a=state.test.answers[state.test.i],rev=!!state.test.review[state.test.i];return `<main class="page"><div class="page-heading"><div><div class="eyebrow">REAL EXAM TEST · ${state.test.i+1}/${state.test.questions.length}</div><h1>${esc(state.type)}</h1><p>Deselect remains available until Final Submit. Next works even when no answer is selected.</p></div></div>${selector('TEST · TRACK')}<div class="exam-countdown"><strong data-test-countdown>${fmtTime(testRemainingSec())}</strong><span>Exam time left</span></div><div class="exam-pattern-inline"><b>${esc(examPattern().name)}</b> · ${examPattern().questions} Q · ${examPattern().timeMin} min · ${examPattern().marksPerQuestion}/Q · −${examPattern().negativeSession2??examPattern().negative} wrong (Session II where applicable)</div><div class="stats"><div class="stat"><strong>${state.test.i+1}/${state.test.questions.length}</strong><span>Question</span></div><div class="stat"><strong data-live-timer>${fmtTime(nowSec())}</strong><span>Current time</span></div><div class="stat"><strong>${Object.values(state.test.answers).filter(v=>v!==null&&v!==undefined).length}</strong><span>Attempted</span></div><div class="stat"><strong>${Object.values(state.test.review).filter(Boolean).length}</strong><span>Review</span></div></div><br><div class="question"><div class="question-meta"><span>${esc(q.subject||'')}</span><span>${esc(q.source||'Gemini generated')}</span></div><h2>${esc(q.question)}</h2>${q.options.map((o,i)=>`<button class="option ${a===i?'selected':''}" onclick="testPick(${i})"><span class="dot"></span><span>${esc(o)}</span></button>`).join('')}<div class="actions"><button class="secondary" onclick="testReview()">${rev?'★ Remove review':'☆ Mark for review'}</button><button class="secondary" onclick="testNext()">Next →</button><button class="primary" onclick="testSubmit()">Final Submit</button></div><p style="color:var(--muted)">Time starts when this question opens and ends at Next or Final Submit.</p></div></main>`}
function commitTestTime(){state.test.times[state.test.i]=(state.test.times[state.test.i]||0)+nowSec();state.activeStartedAt=Date.now()}
function testPick(i){state.test.answers[state.test.i]=state.test.answers[state.test.i]===i?null:i;render()}
function testReview(){state.test.review[state.test.i]=!state.test.review[state.test.i];render()}
function testNext(){commitTestTime();if(state.test.i<state.test.questions.length-1){state.test.i++;state.activeStartedAt=Date.now();render()}else testSubmit()}
function testSubmit(){commitTestTime();state.test.submitted=true;render()}
function testAnalysisPage(){const qs=state.test.questions;let attempted=0,right=0,total=0;qs.forEach((q,i)=>{const a=state.test.answers[i];if(a!==null&&a!==undefined){attempted++;if(a===q.answer)right++}total+=state.test.times[i]||0});const wrong=attempted-right;const p=state.test.pattern||examPattern();let score=0;qs.forEach((q,i)=>{const a=state.test.answers[i];if(a!==null&&a!==undefined){const neg=(q.session==='II'?Number(p.negativeSession2??p.negative):Number(p.negative));score += a===q.answer?Number(p.marksPerQuestion): -neg;}});return `<main class="page"><div class="page-heading"><div><div class="eyebrow">TEST ANALYSIS</div><h1>Performance & solutions</h1><p>Answer, correctness and exact question-wise time are preserved.</p></div></div><div class="stats"><div class="stat"><strong>${attempted}</strong><span>Attempted</span></div><div class="stat"><strong>${right}</strong><span>Right</span></div><div class="stat"><strong>${wrong}</strong><span>Wrong</span></div><div class="stat"><strong>${attempted?Math.round(right/attempted*100):0}%</strong><span>Accuracy</span></div><div class="stat"><strong>${score.toFixed(2)}</strong><span>Exam-style Score</span></div></div><br><div class="stats"><div class="stat"><strong>${fmtTime(total)}</strong><span>Total Time</span></div><div class="stat"><strong>${fmtTime(qs.length?Math.round(total/qs.length):0)}</strong><span>Avg / Question</span></div><div class="stat"><strong>${qs.length}</strong><span>Total Questions</span></div><div class="stat"><strong>${qs.length-attempted}</strong><span>Unattempted</span></div></div><div class="section-title"><div class="eyebrow">QUESTION-WISE ANALYSIS</div><h2>Answers + time taken</h2></div><div class="analysis-list">${qs.map((q,i)=>{const a=state.test.answers[i],attempted=a!==null&&a!==undefined;return `<article class="analysis-q"><div class="question-meta"><span>Q${i+1} · ${esc(q.sourceType||'AI')}</span><span>⏱ ${fmtTime(state.test.times[i]||0)}</span></div><h3>${esc(q.question)}</h3>${q.options.map((o,j)=>`<div class="ans ${j===q.answer?'green':''} ${attempted&&a===j&&a!==q.answer?'red':''}">${attempted&&a===j?'● Selected · ':''}${j===q.answer?'✓ Correct · ':''}${esc(o)}</div>`).join('')}<div class="solution"><strong>Solution</strong><br>${esc(q.explanation||'')}</div></article>`}).join('')}</div><div class="actions"><button class="primary" onclick="resetTest()">Start New Test</button></div></main>`}
function resetTest(){state.test={questions:[],i:0,answers:{},times:{},review:{},submitted:false,startedAt:null,pattern:null};state.activeStartedAt=Date.now();render()}
function profile(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">PROFILE / LOGIN</div><h1>${state.authUser?'Student profile':'Welcome to SamStudy'}</h1><p>${state.authUser?esc(state.authUser.email):'Sign in with Google, Gmail/email-password or phone OTP.'}</p></div></div>${state.authUser?profileLoggedIn():loginCard()}</main>`}
function loginCard(){return `<div class="card"><h2>Login / Sign up</h2><div class="login-actions"><button class="wide" onclick="loginGoogle()">Continue with Google</button><button onclick="openEmailAuth('login')">Login with Gmail / Email</button><button onclick="openPhoneAuth()">Login with Phone</button><button onclick="openEmailAuth('signup')">Create New Account</button><button onclick="openEmailAuth('reset')">Forgot Password</button></div><div class="auth-note">Email/password login works directly through the SamStudy backend. Google and Phone use Firebase when Firebase Web values are configured in Render.</div></div>`}
function profileLoggedIn(){const admin=isAdmin();const u=state.authUser;const name=state.profile.name||u.displayName||u.email||u.phoneNumber||'Student';const verification=u.email?(u.emailVerified?'<span class="verified">✓ Gmail verified</span>':'<button class="mini-action" onclick="verifyGmail()">Send Gmail verification</button>'):'<span class="mini-pill">Phone account</span>';return `<div class="panel profile-main" style="padding:24px"><div class="profile profile-top"><div class="profile-photo-wrap"><img class="avatar profile-avatar" src="${esc(state.profile.photo||'/static/assets/samstudy-logo.png')}" alt="Profile photo"><div class="photo-actions"><button class="secondary" onclick="openCamera()">📷 Use camera</button><label class="secondary">Choose photo<input id="photo" type="file" accept="image/*" style="display:none"></label></div></div><div class="profile-details"><h2>${esc(name)}</h2><div class="field compact-field"><label>Student name</label><input id="studentName" value="${esc(name)}" placeholder="Student name"><button class="secondary" onclick="saveStudentName()">Save name</button></div><div class="profile-info-grid"><div><span class="profile-label">Course / Exam</span><strong>${esc(state.parent)}</strong></div><div><span class="profile-label">Course type / Exam type</span><strong>${esc(state.type)}</strong></div><div><span class="profile-label">Gmail verification</span><strong>${verification}</strong></div><div><span class="profile-label">Account</span><strong>${admin?'Developer':'Student'}</strong></div></div><div class="actions"><button class="danger" onclick="logout()">Logout</button><button class="secondary" onclick="go('profileType')">Change Course / Exam</button></div></div></div></div><div class="section-title"><div class="eyebrow">LEARNING TRACK</div><h2>Select Course or Government Exam</h2></div>${selector('PROFILE · TRACK')}<button class="primary" onclick="go('profileType')">Continue → Select ${state.kind==='exam'?'Exam Type':'Course Type'}</button><div class="section-title"><div class="eyebrow">STUDYSHIELD</div><h2>All apps & individual timing</h2></div><div class="permission-grid"><div class="permission profileColorCard shieldConnect"><div class="shieldIcon">🛡</div><div><strong>StudyShield</strong><span>Add apps and set a separate daily limit + reset time for every app.</span><button class="primary" onclick="go('shield')">Open StudyShield</button></div></div>${admin?`<div class="permission profileColorCard"><strong>Developer tools</strong><span>Add batches/content to the selected track.</span><button class="primary" onclick="go('admin')">Open Developer Panel</button></div>`:''}</div><div class="section-title"><div class="eyebrow">CONNECT WITH SAMSTUDY</div><h2>Follow the channel & Instagram</h2></div><div class="social-links"><a class="social-card youtube" href="https://www.youtube.com/@Sam_malik77" target="_blank" rel="noopener noreferrer"><span>▶</span><div><strong>YouTube</strong><small>Sam_malik77</small></div></a><a class="social-card instagram" href="https://www.instagram.com/Sam_shad132/" target="_blank" rel="noopener noreferrer"><span>◎</span><div><strong>Instagram</strong><small>Sam_shad132</small></div></a></div><div class="section-title"><div class="eyebrow">PERMISSIONS</div><h2>Camera & account</h2></div><div class="permission-grid"><div class="permission profileColorCard"><strong>Camera / photo</strong><span>Allow camera access to capture your profile photo.</span><button class="secondary" onclick="requestCamera()">Allow camera</button></div><div class="permission profileColorCard"><strong>Logout</strong><span>End the current Firebase session.</span><button class="danger" onclick="logout()">Logout</button></div></div></main>`}function profileType(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">PROFILE · STEP 2</div><h1>${esc(state.parent)}</h1><p>Select the exact ${state.kind==='exam'?'Exam Type':'Course Type'}.</p></div></div>${selector('PROFILE · TYPE SELECTOR')}<div class="card"><h3>Selected profile</h3><p>${state.kind==='exam'?'Government Exam':'Course'}: <b>${esc(state.parent)}</b></p><p>${state.kind==='exam'?'Exam Type':'Course Type'}: <b>${esc(state.type)}</b></p><button class="primary" onclick="go('batches')">Save & view relevant batches →</button></div></main>`}
function ai(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">AI DOUBT SOLVER · GEMINI</div><h1>Ask your doubt.</h1><p>Text, voice or photo. Gemini solves the question and returns a clear step-by-step explanation.</p></div></div>${selector('AI DOUBT · SELECTED TRACK')}<div class="card"><div class="field"><label>Your doubt</label><textarea id="doubt" rows="6" placeholder="Example: Solve x² − 5x + 6 = 0"></textarea></div><div class="actions"><button class="primary" onclick="solveAI()">Solve with Gemini</button><button class="secondary" onclick="speak()">🎙 Speak</button><button class="secondary" onclick="chooseDoubtPhoto()">📷 Photo</button></div><input id="doubtPhoto" type="file" accept="image/*" capture="environment" style="display:none"><div id="answer"></div></div></main>`}
async function solveAI(){const q=$('#doubt')?.value.trim();const image=state.doubtImage||null;if(!q&&!image)return toast('Enter a doubt or choose a photo first');$('#answer').innerHTML='<div class="solution">Gemini is solving…</div>';try{const r=await api('/api/ai/doubt',{question:q, image,track:{exam:state.parent,type:state.type,subject:subjects()[0]||''}});$('#answer').innerHTML=`<div class="solution ai-output"><strong>Gemini answer</strong><div class="ai-math">${esc(r.answer||r.text||'No answer')}</div></div>`;window.MathJax?.typesetPromise?.([$('#answer')])}catch(e){$('#answer').innerHTML=`<div class="solution">${esc(e.message)}</div>`}}
function speak(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voice input is not supported here');const r=new SR();r.lang='en-IN';r.onresult=e=>{$('#doubt').value=e.results[0][0].transcript;toast('Voice captured')};r.start()}
function chooseDoubtPhoto(){$('#doubtPhoto')?.click()}
async function generateQuiz(){const count=Number($('#quizCount').value);state.quiz.count=count;state.quiz.questions=[];render();try{const r=await api('/api/ai/quiz',{mode:'quiz',count,exam:state.parent,type:state.type,subjects:subjects()});state.quiz.questions=r.questions;state.quiz.i=0;state.quiz.answers={};state.quiz.times={};state.quiz.submitted=false;state.activeStartedAt=Date.now();render()}catch(e){toast(e.message);render()}}
async function generateTest(){try{const p=examPattern();const r=await api('/api/ai/quiz',{mode:'test',count:p.questions,exam:state.parent,type:state.type,subjects:subjects(),pattern:p});state.test.questions=r.questions;state.test.pattern=p;state.test.i=0;state.test.answers={};state.test.times={};state.test.review={};state.test.submitted=false;state.test.startedAt=Date.now();state.activeStartedAt=Date.now();render()}catch(e){toast(e.message)}}
async function api(url,data){const headers={'Content-Type':'application/json'};if(firebaseAuth?.currentUser)headers.Authorization='Bearer '+await firebaseAuth.currentUser.getIdToken();const res=await fetch(url,{method:'POST',headers,body:JSON.stringify(data)});const d=await res.json().catch(()=>({}));if(!res.ok)throw new Error(d.error||'Request failed');return d}
function three(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">3-D LEARNING · GEMINI</div><h1>See the concept.</h1><p>Gemini turns a concept into a structured scene; Three.js renders the scene interactively.</p></div></div><div class="card"><div class="field"><label>Concept</label><input id="threeConcept" placeholder="Example: DNA double helix, solar system, transistor"></div><div class="actions"><button class="primary" onclick="generate3D()">Generate Live 3-D Scene</button></div></div><div class="three-stage" id="threeStage"><div style="padding:24px;color:#a9bed0">Enter a concept and generate the scene.</div></div><div class="card" id="threeText" style="margin-top:14px"></div></main>`}
async function generate3D(){const c=$('#threeConcept').value.trim();if(!c)return toast('Enter a concept');$('#threeText').innerHTML='<div class="solution">Gemini is designing the scene…</div>';try{const r=await api('/api/ai/3d',{concept:c,track:{exam:state.parent,type:state.type}});$('#threeText').innerHTML=`<div class="solution ai-output"><strong>${esc(r.title||c)}</strong>\n${esc(r.explanation||'')}</div>`;await loadThree();renderThree(r.scene||{objects:[{type:'sphere',color:'#2ab9ff',scale:1}]})}catch(e){$('#threeText').innerHTML=`<div class="solution">${esc(e.message||'3-D library could not be loaded.')}</div>`}}
function renderThree(scene){const el=$('#threeStage');if(!el||!THREE)return;el.innerHTML='';const W=el.clientWidth,H=el.clientHeight;const s=new THREE.Scene();s.background=new THREE.Color(0x050b12);const cam=new THREE.PerspectiveCamera(45,W/H,.1,100);cam.position.set(0,1.5,6);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setSize(W,H);renderer.setPixelRatio(Math.min(devicePixelRatio,2));el.appendChild(renderer.domElement);const light=new THREE.PointLight(0xffffff,2.4);light.position.set(3,4,4);s.add(light);s.add(new THREE.AmbientLight(0x66bbff,1.2));(scene.objects||[]).forEach((o,i)=>{let g;if(o.type==='box')g=new THREE.BoxGeometry(1,1,1);else if(o.type==='torus')g=new THREE.TorusGeometry(.75,.22,24,60);else g=new THREE.SphereGeometry(.7,32,24);const m=new THREE.MeshStandardMaterial({color:o.color||'#2ab9ff',metalness:.35,roughness:.3});const mesh=new THREE.Mesh(g,m);mesh.position.set((i%3-1)*1.5,Math.floor(i/3)*1.2-.5,0);const sc=Number(o.scale||1);mesh.scale.setScalar(sc);s.add(mesh)});function loop(t){s.rotation.y=t*.00025;renderer.render(s,cam);requestAnimationFrame(loop)}requestAnimationFrame(loop)}
function shield(){return `<main class="page"><div class="page-heading"><div><div class="eyebrow">STUDYSHIELD</div><h1>Control every app.</h1><p>Add every app you want to control and set its own daily timing.</p></div></div><div class="card"><div class="shield-add-grid"><div class="field"><label>App / site name</label><input id="shieldName" placeholder="Instagram, YouTube, Chrome…"></div><div class="field"><label>Daily limit (minutes)</label><input id="shieldLimit" type="number" min="1" max="1440" value="60"></div><div class="field"><label>Reset time</label><input id="shieldStart" type="time" value="00:00"></div><button class="primary" onclick="addShieldFromForm()">Add App</button></div><div class="shield-all-apps"><button class="mini-pill" onclick="addCommonShieldApps()">＋ Add common apps</button><button class="mini-pill" onclick="addStudyApps()">＋ Add study apps</button><button class="mini-pill" onclick="addAllAppPlaceholders()">＋ Add all common installed-app slots</button><button class="mini-pill" onclick="startShieldSession()">▶ Start Focus Session</button></div><div class="auth-note">On Android, the included StudyShield companion can enumerate launchable apps and enforce each configured limit after Usage Access + Accessibility permissions are granted. Browser-only mode stores all limits locally.</div></div><div class="section-title"><div class="eyebrow">YOUR APPS</div><h2>Individual timing</h2><p>Every row has its own daily limit and reset time.</p></div><div class="shield-apps">${state.shield.length?state.shield.map((x,i)=>`<div class="shield-item"><div><strong>${esc(x.name)}</strong><div class="app-note">Used today: ${Math.round(x.used||0)} min · resets ${esc(x.start||'00:00')}</div></div><input aria-label="${esc(x.name)} daily limit" type="number" min="1" max="1440" value="${x.limit}" onchange="updateShield(${i},this.value)"><input aria-label="${esc(x.name)} reset time" type="time" value="${x.start||'00:00'}" onchange="updateShieldStart(${i},this.value)"><button class="danger" ${x.lockedUntil&&Date.now()<x.lockedUntil?'disabled':''} onclick="removeShield(${i})">${x.lockedUntil&&Date.now()<x.lockedUntil?'Locked until reset':'Remove'}</button></div>`).join(''):'<div class="card"><p>No apps added yet.</p></div>'}</div><div class="shield-social-space"><div class="section-title"><div class="eyebrow">SAMSTUDY</div><h2>Stay connected</h2></div><div class="social-links"><a class="social-card youtube" href="https://www.youtube.com/@Sam_malik77" target="_blank" rel="noopener noreferrer"><span>▶</span><div><strong>YouTube</strong><small>Sam_malik77</small></div></a><a class="social-card instagram" href="https://www.instagram.com/Sam_shad132/" target="_blank" rel="noopener noreferrer"><span>◎</span><div><strong>Instagram</strong><small>Sam_shad132</small></div></a></div></div></main>`}function addShieldFromForm(){const name=$('#shieldName')?.value.trim();const limit=Number($('#shieldLimit')?.value||60);const start=$('#shieldStart')?.value||'00:00';if(!name)return toast('Enter an app/site name');state.shield.push({name,limit:Math.min(1440,Math.max(1,limit)),used:0,start,updated:Date.now(),lockedUntil:Date.now()+24*60*60*1000});persist();render();toast(name+' added')}
function updateShieldStart(i,v){if(!state.shield[i])return;state.shield[i].start=v||'00:00';persist();render()}
function addCommonShieldApps(){const apps=['YouTube','Instagram','WhatsApp','Facebook','Chrome','Gmail','Google Maps','Telegram','Spotify','Netflix'];let n=0;for(const name of apps){if(!state.shield.some(x=>x.name.toLowerCase()===name.toLowerCase())){state.shield.push({name,limit:60,used:0,start:'00:00',updated:Date.now(),lockedUntil:Date.now()+24*60*60*1000});n++}}persist();render();toast(n+' common apps added')}
function addAllAppPlaceholders(){const apps=['YouTube','Instagram','WhatsApp','Facebook','Chrome','Gmail','Google Maps','Telegram','Spotify','Netflix','Amazon','Flipkart','Snapchat','X','Discord','Microsoft Teams','Zoom','Google Classroom','Google Drive','ChatGPT','Gemini','Notion','Coursera','Udemy'];let n=0;for(const name of apps){if(!state.shield.some(x=>x.name.toLowerCase()===name.toLowerCase())){state.shield.push({name,limit:60,used:0,start:'00:00',updated:Date.now(),lockedUntil:Date.now()+24*60*60*1000});n++}}persist();render();toast(n+' app slots added')}
function addStudyApps(){const apps=['Google Classroom','Google Drive','Chrome','YouTube','ChatGPT','Gemini','Notion','Microsoft Teams','Zoom','Coursera','Udemy'];let added=0;for(const name of apps){if(!state.shield.some(x=>x.name.toLowerCase()===name.toLowerCase())){state.shield.push({name,limit:60,used:0,start:'00:00',updated:Date.now(),lockedUntil:Date.now()+24*60*60*1000});added++}}persist();render();toast(added+' study apps added')}
function addShield(){const name=prompt('App/site name');if(!name)return;const limit=Number(prompt('Daily limit in minutes','60'));if(!limit)return;state.shield.push({name,limit,used:0,updated:Date.now(),lockedUntil:Date.now()+24*60*60*1000});persist();render()}
function updateShield(i,v){state.shield[i].limit=Math.max(1,Number(v)||1);persist();render()}
function removeShield(i){const x=state.shield[i];if(!x)return;if(x.lockedUntil&&Date.now()<x.lockedUntil)return toast('This app is locked in StudyShield until the next daily reset.');state.shield.splice(i,1);persist();render()}
function startShieldSession(){const mins=Number(prompt('Focus session minutes','25'));if(!mins)return;let end=Date.now()+mins*60000;localStorage.setItem('ss-focus-end',String(end));toast('Focus session started for '+mins+' minutes')}
function admin(){if(!isAdmin())return `<main class="page"><div class="card"><h2>Developer access required</h2><p>Sign in with ${ADMIN_EMAIL} to open this panel.</p></div></main>`;return `<main class="page"><div class="page-heading"><div><div class="eyebrow">DEVELOPER PANEL</div><h1>Manage SamStudy</h1><p>Add batches, resources, books and content. Backend checks the developer account.</p></div></div><div class="card admin-grid"><div class="field"><label>Batch name</label><input id="adminBatch" placeholder="SSC CHSL Foundation"></div><div class="field"><label>Course / Exam</label><input id="adminParent" value="${esc(state.parent)}"></div><div class="field"><label>Type</label><input id="adminType" value="${esc(state.type)}"></div><div class="field"><label>Subject</label><input id="adminSubject" placeholder="Quantitative Aptitude"></div><div class="field full"><label>Resource / content URL</label><input id="adminUrl" placeholder="https://..."></div><div class="field"><label>Resource type</label><select id="adminResourceKind"><option>Notes</option><option>Lectures</option></select></div><div class="full actions"><button class="primary" onclick="adminAddBatch()">Add Batch</button><button class="secondary" onclick="adminAddResource()">Add Resource</button></div><div class="field full"><label>Upload book PDF for verification</label><input id="adminBookFile" type="file" accept="application/pdf,.pdf"><button class="secondary" onclick="adminUploadFile('book')">Upload Book</button></div><div class="field full"><label>Upload notes/content</label><input id="adminContentFile" type="file"><button class="secondary" onclick="adminUploadFile('content')">Upload Content</button></div><div id="adminStatus" class="auth-note full"></div></div></main>`}
async function adminUploadFile(kind){const input=$(kind==='book'?'#adminBookFile':'#adminContentFile');const f=input?.files?.[0];if(!f)return toast('Choose a file first');const fd=new FormData();fd.append('file',f);fd.append('kind',kind);try{const headers={};if(firebaseAuth?.currentUser)headers.Authorization='Bearer '+await firebaseAuth.currentUser.getIdToken();const r=await fetch('/api/admin/upload',{method:'POST',headers,body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Upload failed');toast('Uploaded '+d.name)}catch(e){toast(e.message)}}
async function refreshChanges(){try{state.catalogChanges=await fetch('/api/catalog-changes').then(r=>r.json())}catch(_){state.catalogChanges=[]}}
async function adminAddBatch(){const name=$('#adminBatch').value.trim();if(!name)return toast('Batch name required');try{await api('/api/admin/batch',{name,parent:$('#adminParent').value,type:$('#adminType').value});await refreshChanges();toast('Batch added');render()}catch(e){toast(e.message)}}
async function adminAddResource(){const url=$('#adminUrl').value.trim();if(!url)return toast('Resource URL required');try{await api('/api/admin/resource',{parent:$('#adminParent').value,type:$('#adminType').value,subject:$('#adminSubject').value,url,resourceKind:$('#adminResourceKind').value});await refreshChanges();toast('Resource added')}catch(e){toast(e.message)}}
async function addBatch(){const name=$('#newBatch').value.trim();if(!name)return toast('Enter a batch name');try{await api('/api/admin/batch',{name,parent:state.parent,type:state.type});await refreshChanges();toast('Batch added');render()}catch(e){toast(e.message)}}
function isAdmin(){return !!state.authUser && (state.authUser.email||'').toLowerCase()===ADMIN_EMAIL}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';persist();render()}
function go(p){if(state.page==='quiz'&&!state.quiz.submitted&&state.quiz.questions.length){commitQuizTime();state.activeStartedAt=null}if(state.page==='test'&&!state.test.submitted&&state.test.questions.length){commitTestTime();state.activeStartedAt=null}state.page=p;history.replaceState({},'',p==='home'?'/':'/?page='+encodeURIComponent(p));if(p==='quiz'&&state.quiz.questions.length&&!state.quiz.submitted)state.activeStartedAt=Date.now();if(p==='test'&&state.test.questions.length&&!state.test.submitted)state.activeStartedAt=Date.now();render();scrollTo({top:0,behavior:'smooth'})}
function modal(content){const m=$('#modal');m.innerHTML=`<div class="modal-box">${content}</div>`;m.classList.add('show')}
function closeModal(){const m=$('#modal');m.classList.remove('show');m.innerHTML=''}
function openEmailAuth(mode){if(mode==='reset'){modal(`<h2>Forgot password</h2><div class="field"><label>Email</label><input id="authEmail" type="email" placeholder="you@gmail.com"></div><div class="actions"><button class="primary" onclick="resetPassword()">Send reset email</button><button class="secondary" onclick="closeModal()">Cancel</button></div>`);return}modal(`<h2>${mode==='signup'?'Create new account':'Login with Gmail / Email'}</h2><div class="field"><label>Email</label><input id="authEmail" type="email" placeholder="you@gmail.com"></div><div class="field"><label>Password</label><input id="authPass" type="password" placeholder="••••••••"></div><div class="actions"><button class="primary" onclick="emailAuth('${mode}')">${mode==='signup'?'Create account':'Login'}</button><button class="secondary" onclick="closeModal()">Cancel</button></div>`)}
async function emailAuth(mode){const e=$('#authEmail')?.value.trim(),p=$('#authPass')?.value||'';if(!e||!p)return toast('Enter email and password');try{const local=await fetch('/api/auth/'+(mode==='signup'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e,password:p})});const d=await local.json().catch(()=>({}));if(local.ok){state.authUser=d.user;state.profile.name=d.user.name||state.profile.name;state.profile.email=d.user.email;persist();closeModal();render();return toast(mode==='signup'?'Account created':'Login successful')}if(!firebaseAuth)return toast(d.error||'Login failed');throw new Error(d.error||'Local login failed')}catch(err){if(!firebaseAuth)return toast(err.message);try{if(mode==='signup')await createUserWithEmailAndPassword(firebaseAuth,e,p);else await signInWithEmailAndPassword(firebaseAuth,e,p);closeModal();toast('Firebase login successful')}catch(e2){toast(e2.message)}}}
async function resetPassword(){toast('For backend accounts, use your email provider or configure Firebase password reset.')}
async function loginGoogle(){if(!firebaseAuth)return toast('Google login needs Firebase Web configuration in Render. Email/password login works now.');const p=new GoogleAuthProvider();try{await signInWithPopup(firebaseAuth,p);toast('Google login successful')}catch(e){try{await signInWithRedirect(firebaseAuth,p)}catch(err){toast(err.message)}}}
async function openPhoneAuth(){if(!firebaseAuth){if(!(await loadFirebase()))return toast('Firebase login library is unavailable.');} modal(`<h2>Login with Phone</h2><div class="field"><label>Phone number</label><input id="phone" type="tel" placeholder="+91XXXXXXXXXX"></div><div id="recaptcha"></div><div class="actions"><button class="primary" onclick="sendPhoneOtp()">Send OTP</button><button class="secondary" onclick="closeModal()">Cancel</button></div>`);setTimeout(()=>{try{recaptcha=new RecaptchaVerifier(firebaseAuth,'recaptcha',{size:'normal'});recaptcha.render()}catch(e){toast('Phone login setup failed: '+e.message)}},50)}
async function sendPhoneOtp(){try{phoneConfirmation=await signInWithPhoneNumber(firebaseAuth,$('#phone').value.trim(),recaptcha);modal(`<h2>Enter OTP</h2><div class="field"><label>SMS code</label><input id="otp" inputmode="numeric" maxlength="6"></div><div class="actions"><button class="primary" onclick="verifyOtp()">Verify OTP</button></div>`)}catch(e){toast(e.message)}}
async function verifyOtp(){try{await phoneConfirmation.confirm($('#otp').value.trim());closeModal();toast('Phone login successful')}catch(e){toast(e.message)}}
async function saveStudentName(){const n=$('#studentName')?.value.trim();if(!n)return toast('Enter your name');state.profile.name=n;persist();if(firebaseAuth?.currentUser){try{await firebaseAuth.currentUser.updateProfile({displayName:n})}catch(e){}}render();toast('Student name saved')}
async function verifyGmail(){if(!firebaseAuth?.currentUser)return;try{await sendEmailVerification(firebaseAuth.currentUser);toast('Verification email sent to '+firebaseAuth.currentUser.email)}catch(e){toast(e.message)}}
async function logout(){try{await fetch('/api/auth/logout',{method:'POST'})}catch(_){} if(firebaseAuth){try{await signOut(firebaseAuth)}catch(_){}} state.authUser=null;render();toast('Logged out')}
async function requestCamera(){try{const s=await navigator.mediaDevices.getUserMedia({video:true});s.getTracks().forEach(t=>t.stop());toast('Camera permission granted')}catch(e){toast('Camera permission denied or unavailable')}}
function openCamera(){requestCamera()}
function downloadDemo(){const blob=new Blob([`SamStudy\n${state.parent} · ${state.type}\nGenerated on ${new Date().toLocaleString()}`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SamStudy-learning-info.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function render(){ensure();document.documentElement.dataset.theme=state.theme;document.body.dataset.page=state.page;let body=state.page==='home'?home():state.page==='batches'?batchesPage():state.page==='subjects'?subjectsPage():state.page==='resource'?resourcePage():state.page==='quiz'?quizPage():state.page==='test'?testPage():state.page==='profile'?profile():state.page==='profileType'?profileType():state.page==='ai'?ai():state.page==='three'?three():state.page==='shield'?shield():state.page==='admin'?admin():home();$('#app').innerHTML=header()+body+nav();bindSelectors();if(state.page==='profile')$('#photo')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.profile.photo=r.result;persist();render()};r.readAsDataURL(f)});if(state.page==='ai')$('#doubtPhoto')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.doubtImage={mimeType:f.type,data:r.result.split(',')[1]};toast('Photo attached');};r.readAsDataURL(f)});}
window.go=go;window.toggleTheme=toggleTheme;window.quizPick=quizPick;window.quizNext=quizNext;window.quizSubmit=quizSubmit;window.resetQuiz=resetQuiz;window.generateQuiz=generateQuiz;window.testPick=testPick;window.testReview=testReview;window.testNext=testNext;window.testSubmit=testSubmit;window.resetTest=resetTest;window.generateTest=generateTest;window.openBatch=openBatch;window.openResource=openResource;window.generateChapterPDF=generateChapterPDF;window.openLectureSearch=openLectureSearch;window.downloadDemo=downloadDemo;window.solveAI=solveAI;window.speak=speak;window.chooseDoubtPhoto=chooseDoubtPhoto;window.generate3D=generate3D;window.addShield=addShield;window.updateShield=updateShield;window.removeShield=removeShield;window.startShieldSession=startShieldSession;window.adminAddBatch=adminAddBatch;window.adminAddResource=adminAddResource;window.adminUploadFile=adminUploadFile;window.addBatch=addBatch;window.openEmailAuth=openEmailAuth;window.emailAuth=emailAuth;window.resetPassword=resetPassword;window.loginGoogle=loginGoogle;window.openPhoneAuth=openPhoneAuth;window.sendPhoneOtp=sendPhoneOtp;window.verifyOtp=verifyOtp;window.closeModal=closeModal;window.logout=logout;window.requestCamera=requestCamera;window.openCamera=openCamera;window.saveStudentName=saveStudentName;window.verifyGmail=verifyGmail;window.addShieldFromForm=addShieldFromForm;window.updateShieldStart=updateShieldStart;window.addCommonShieldApps=addCommonShieldApps;window.addStudyApps=addStudyApps;window.addAllAppPlaceholders=addAllAppPlaceholders;window.toast=toast;
async function init(){
  render();
  try{
    const me=await fetch('/api/auth/me',{cache:'no-store'}).then(r=>r.json());
    if(me.user){state.authUser=me.user;state.profile.name=me.user.name||state.profile.name;state.profile.email=me.user.email||state.profile.email;persist();render();}
    const cfg=await fetch('/api/config',{cache:'no-store'}).then(r=>r.json());
    try{state.catalogChanges=await fetch('/api/catalog-changes',{cache:'no-store'}).then(r=>r.json())}catch(_){state.catalogChanges=[]}
    if(cfg.firebaseConfigured&&cfg.firebase?.apiKey){
      const ready=await loadFirebase();
      if(ready){
        const firebaseApp=initializeApp(cfg.firebase);
        firebaseAuth=getAuth(firebaseApp);
        onAuthStateChanged(firebaseAuth,u=>{
          if(u){state.authUser=u;state.profile.name=u.displayName||state.profile.name||'';state.profile.email=u.email||u.phoneNumber||'';persist();render();}
          else if(!state.authUser?.local){state.authUser=null;render();}
        });
      }else{ toast('Firebase login library could not load. The website is still usable; retry login later.') }
    }else{
      setTimeout(()=>toast('Login is ready after Firebase Web values are added in Render Environment Variables.'),350);
    }
  }catch(e){
    state.catalogChanges=[];
    toast('Backend config unavailable. The local catalog is still available.');
  }
  if(!timerHandle){timerHandle=setInterval(()=>{
    if(state.page==='quiz'&&!state.quiz.submitted){document.querySelectorAll('[data-live-timer]').forEach(el=>el.textContent=fmtTime(nowSec()))}
    if(state.page==='test'&&!state.test.submitted){document.querySelectorAll('[data-live-timer]').forEach(el=>el.textContent=fmtTime(nowSec()));document.querySelectorAll('[data-test-countdown]').forEach(el=>el.textContent=fmtTime(testRemainingSec()));if(testRemainingSec()<=0){commitTestTime();state.test.submitted=true;render();toast('Exam time ended — test submitted automatically')}}
  },250)}
}

init();
